//! The default hotkeys: the cheat sheet (Super K) and Settings › Hotkeys start from these. Generated by tools/build.py from tokens.json. Do not edit.

/// Where a hotkey works.
#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub enum Scope {
    /// Anywhere in the session.
    Global,
    /// Only while the theme picker is open.
    ThemePicker,
}

/// One action with its keys. Keys are written as on the cheat sheet, separated by spaces: "Super Shift Return".
/// "Super 1–9" stands for nine bindings, "Super Arrows" for four.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Hotkey {
    pub id: &'static str,
    pub group: &'static str,
    pub action: &'static str,
    pub keys: &'static str,
    /// What it acts on, the second line on the cheat sheet.
    pub target: &'static str,
    pub scope: Scope,
}

impl Hotkey {
    /// The keys one by one.
    pub fn key_list(&self) -> impl Iterator<Item = &'static str> {
        self.keys.split(' ')
    }
}

